use super::*;

/// What the battery found.
///
/// The CONTROL is printed with everything else rather than filtered out, because a mediocre result
/// read in isolation looks like something and read beside a coin flip does not. The t-statistic and
/// the bar it had to clear are printed together for the same reason — a number without its
/// threshold is a number somebody rounds up in their head.
pub fn render_backtest(reports: &[(String, Vec<crate::evaluate::Evaluation>, Vec<String>)], bps: f64) -> String {
    let mut out = String::new();
    let pc = |x: f64| format!("{:.1}%", x * 100.0);
    out.push_str(&format!("costs charged at {bps} bps one way, on every change in position\n"));

    for (symbol, evs, notes) in reports {
        out.push_str(&format!("\n{symbol}\n"));
        if evs.is_empty() {
            for n in notes {
                out.push_str(&format!("  · {n}\n"));
            }
            continue;
        }
        out.push_str("  signal            verdict                  net     hold      o/s        t   bar\n");
        for e in evs {
            let (net, bench, oos) = (
                e.net.map(|s| pc(s.total_return)).unwrap_or_else(|| "—".into()),
                e.benchmark.map(|s| pc(s.total_return)).unwrap_or_else(|| "—".into()),
                e.out_of_sample.map(|s| pc(s.total_return)).unwrap_or_else(|| "—".into()),
            );
            out.push_str(&format!(
                "  {:<16}  {:<20}{:>7}{:>9}{:>9}{:>9}{:>6.2}\n",
                clip(&e.signal, 16),
                e.verdict.label(),
                net,
                bench,
                oos,
                e.t_stat.map(|t| format!("{t:.2}")).unwrap_or_else(|| "—".into()),
                e.t_required
            ));
        }
        // The reason for the TOP result only — the rest are visible above and a wall of prose
        // buries the table that is doing the work.
        if let Some(top) = evs.first() {
            out.push_str(&format!("\n  {}: {}\n", top.signal, top.why));
        }
        let control = evs.iter().find(|e| e.signal == "null-control");
        if let (Some(c), Some(top)) = (control, evs.first()) {
            if top.signal != "null-control" {
                // The only part that is evidence is the DIFFERENCE between a candidate and a coin.
                out.push_str(&format!(
                    "  the coin flip scored {} net for comparison — the gap is the only part that is evidence\n",
                    c.net.map(|s| pc(s.total_return)).unwrap_or_else(|| "—".into())
                ));
            }
        }
        for n in notes {
            out.push_str(&format!("  · {n}\n"));
        }
        let mut seen: Vec<&str> = Vec::new();
        for e in evs {
            for c in &e.caveats {
                if !seen.contains(&c.as_str()) {
                    seen.push(c);
                    out.push_str(&format!("  · {c}\n"));
                }
            }
        }
    }
    out
}
